import{createLogger,formatError}from"#internal/logging.js";const log=createLogger(`harness.instrumentation-lifecycle`);function createInstrumentationHooks(e){let r=new WeakMap,publish=async t=>{for(let n of e){let e=n.events?.[t.type];if(e!==void 0)try{await e(t)}catch(e){warn(t.type,e)}}},before=async(t,n)=>{let i=r.get(n.scope)??new Map;r.set(n.scope,i);for(let[r,a]of e.entries()){let e=a.events?.[t]?.before;if(e!==void 0)try{let t=await e(n);i.set(relatedStateKey(r,n.id),t)}catch(e){warn(`${t}.before`,e)}}},after=async(t,n)=>{let i=r.get(n.scope);for(let[r,a]of e.entries()){let e=a.events?.[t]?.after,o=relatedStateKey(r,n.id);if(e===void 0||!i?.has(o))continue;let s=i.get(o);i.delete(o);try{await e(n,s)}catch(e){warn(`${t}.after`,e)}}},warn=(e,r)=>{log.warn(`instrumentation provider failed`,{boundary:e,error:formatError(r)})};return{after,before,publish}}function relatedStateKey(e,t){return`${e}:${t}`}export{createInstrumentationHooks};